Handle: func(s string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
	p := n.(*pageState)
	if p.m != nil && p.m.pageConfig != nil && p.m.pageConfig.IsFromContentAdapter && p.m.pathInfo != nil {
		// Pages created by a content adapter are associated with
		// the _content.gotmpl file that created them, so we cannot
		// use the file's path info. Use the page's canonical path.
		add(p.m.pathInfo.BaseNameNoIdentifier(), p)
	} else if p.File() != nil {
		add(p.File().FileInfo().Meta().PathInfo.BaseNameNoIdentifier(), p)
	}
	return false, nil
},

