	if p.File() != nil {
		add(p.File().FileInfo().Meta().PathInfo.BaseNameNoIdentifier(), p)
	} else if p.m != nil && p.m.pageConfig != nil && p.m.pageConfig.IsFromContentAdapter && p.m.pathInfo != nil {
		// Pages created by content adapters have no source file,
		// so index them by the base name of their path.
		fmt.Println("DEBUG adapter walk", s, p.m.pathInfo.Path(), p.m.pathInfo.IsBundle(), p.m.pathInfo.Container(), p.m.pathInfo.Base(), p.m.pathInfo.NameNoIdentifier())
		add(p.m.pathInfo.BaseNameNoIdentifier(), p)
	}
	return false, nil
},

